export const circuitViewBox = "0 0 500 500";

// Helper function to get a circuit path by name (case-insensitive, partial match)
export function getCircuitPath(name: string): string | null {
  const normalized = name.toLowerCase().trim();
  
  // Exact match first
  if (circuitPaths[normalized]) {
    return circuitPaths[normalized];
  }
  
  // Partial match
  for (const [key, path] of Object.entries(circuitPaths)) {
    if (key.includes(normalized) || normalized.includes(key)) {
      return path;
    }
  }
  
  return null;
}

// Default viewBox for all FastF1-generated paths
export const defaultViewBox = "0 0 500 500";

